WITH scored AS (SELECT *, FIRST_VALUE(amount, TRUE) OVER (ORDER BY shipping_fee, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_amount, LAST_VALUE(discount, TRUE) OVER (PARTITION BY store_id ORDER BY order_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_discount, ROUND(amount / SUM(amount) OVER (PARTITION BY store_id), 4) AS amount_share FROM orders) SELECT store_id, DATE_TRUNC('YEAR', order_date) AS year_start, CASE WHEN shipping_fee >= 38 THEN 'PREMIUM' ELSE 'STANDARD' END AS shipping_fee_tier, CORR(shipping_fee, amount) AS corr_shipping_fee_amount, COUNT_IF(channel = 'web') AS web_events, COUNT(CASE WHEN status = 'PENDING' THEN 1 END) AS pending_count, SIZE(COLLECT_SET(status)) AS num_status, SORT_ARRAY(COLLECT_SET(channel)) AS channel_list FROM scored GROUP BY store_id, year_start, shipping_fee_tier HAVING pending_count < 1
